  const num = v => Number(v || 0).toLocaleString();
  function isEmergencyAdmin() { return Boolean(state.auth?.emergency_access_enabled && !state.auth?.oidc_enabled && (!state.auth?.api_key_configured || Boolean(state.adminKey))); }
