  async function api(url, opt = {}) { const headers = { Accept: 'application/json', ...(opt.headers || {}) }; if (state.adminKey) headers['x-admin-key'] = state.adminKey; const method = String(opt.method || 'GET').toUpperCase(); if (url.startsWith('/admin/') && !['GET', 'HEAD', 'OPTIONS'].includes(method)) { if (!state.csrfToken) { const tokenHeaders = { Accept: 'application/json' }; if (state.adminKey) tokenHeaders['x-admin-key'] = state.adminKey; const tokenResponse = await fetch('/admin/api/csrf-token', { headers: tokenHeaders, credentials: 'same-origin', cache: 'no-store' }); const tokenData = await json(tokenResponse); state.csrfToken = tokenData.token || ''; } if (!state.csrfToken) throw Error('CSRF token unavailable'); headers['X-NexaRoute-CSRF'] = state.csrfToken; } return json(await fetch(url, { ...opt, headers, credentials: 'same-origin', cache: 'no-store' })); }
