  function setConnection(ok, bad = false) { $('#connection-dot').className = `status-dot ${ok ? 'good' : bad ? 'bad' : ''}`; $('#connection-text').textContent = ok ? 'Connected' : bad ? 'Unavailable' : 'Connecting'; $('#live-status').textContent = ok ? 'Live' : bad ? 'Offline' : 'Connecting'; $('#live-status').className = `live-status ${ok ? 'live' : bad ? 'offline' : ''}`; }
  const meta = { overview: ['Overview', 'Your routing system at a glance.'], providers: ['Providers', 'Manage upstream connections, models and capabilities.'], routing: ['Routing', 'Shape stable public models into reliable execution paths.'], video: ['Video Studio', 'Create, monitor and safely operate asynchronous video jobs.'], activity: ['Activity', 'Trace real requests, incidents and routing history.'], settings: ['Settings', 'Set operator intent, access and runtime policy.'] };
  const deployments = () => state.snap.deployments || [], routes = () => state.snap.virtual_endpoints || [], healthyCount = () => (state.snap.health || []).filter(x => ['healthy', 'ready'].includes(String(x.status))).length;
