  const statusClass = s => ['healthy', 'ready', 'connected', 'success', 'ok'].includes(String(s).toLowerCase()) ? 'good' : ['cooldown', 'failed', 'degraded', 'error', 'offline'].includes(String(s).toLowerCase()) ? 'bad' : 'warn';
