  function overviewView() { const h = state.snap.health || [], ev = (state.snap.events || []).slice(-8).reverse(), configured = deployments().length, healthy = healthyCount(), routeCount = routes().length, degraded = h.filter(x => ['degraded', 'failed', 'cooldown'].includes(x.status)).length, setupDone = [state.providers.length > 0, routeCount > 0, Boolean(state.snap.client_auth?.enabled)].filter(Boolean).length; return `<section class="hero-panel"><div><span class="eyebrow">Operations command center</span><h2>Know what is routing before you touch a setting.</h2><p>Real backend state, layered health and explainable paths — no synthetic movement.</p><div class="hero-actions"><button class="button primary" data-action="add-provider">Add provider</button><button class="button secondary" data-go="routing">Create route</button><button class="button ghost" data-go="activity">Inspect activity</button></div></div><div class="hero-orbit" aria-hidden="true"><div class="orbit-ring ring-one"></div><div class="orbit-ring ring-two"></div><div class="orbit-core">NR<span>LIVE</span></div><i></i><i></i><i></i></div></section><div class="metric-grid"><article class="metric-card accent"><span class="metric-icon">↗</span><div><small>Gateway requests</small><strong>${num(state.snap.request_total)}</strong><span class="metric-foot">All-time backend counter</span></div></article><article class="metric-card"><span class="metric-icon">◈</span><div><small>Healthy deployments</small><strong>${healthy}/${num(configured)}</strong><span class="metric-foot">${degraded ? `${degraded} need attention` : 'No active incidents reported'}</span></div></article><article class="metric-card"><span class="metric-icon">⇄</span><div><small>Public routes</small><strong>${num(routeCount)}</strong><span class="metric-foot">Stable model identities</span></div></article><article class="metric-card"><span class="metric-icon">◌</span><div><small>Privacy-safe events</small><strong>${num((state.snap.events || []).length)}</strong><span class="metric-foot">Live stream buffer</span></div></article></div><section class="setup-rail"><div class="setup-rail-head"><div><span class="eyebrow">Quick setup</span><h2>Production path</h2><p>${setupDone}/3 essentials configured. Complete the path in the order that keeps the gateway useful and safe.</p></div><span class="settings-badge">${setupDone === 3 ? 'Ready' : 'In progress'}</span></div><div class="setup-steps"><button class="setup-step ${state.providers.length ? 'done' : 'current'}" data-go="providers"><span>1</span><div><b>Connect a provider</b><small>${state.providers.length ? `${state.providers.length} configured` : 'Add and test your first upstream'}</small></div><strong>${state.providers.length ? '✓' : '→'}</strong></button><button class="setup-step ${routeCount ? 'done' : state.providers.length ? 'current' : ''}" data-go="routing"><span>2</span><div><b>Create a route</b><small>${routeCount ? `${routeCount} public model${routeCount === 1 ? '' : 's'}` : 'Expose one stable model identity'}</small></div><strong>${routeCount ? '✓' : '→'}</strong></button><button class="setup-step ${state.snap.client_auth?.enabled ? 'done' : setupDone === 2 ? 'current' : ''}" data-go="settings"><span>3</span><div><b>Protect client access</b><small>${state.snap.client_auth?.enabled ? 'Client authentication enabled' : 'Enable keys before remote exposure'}</small></div><strong>${state.snap.client_auth?.enabled ? '✓' : '→'}</strong></button></div></section><div class="section-heading"><div><span class="eyebrow">System posture</span><h2>Health, by layer</h2><p>Each layer tells you what is healthy and what to do next.</p></div><button class="button ghost small" data-go="settings">Open settings</button></div><div class="health-grid">${healthLayer('Gateway', 'The control plane is reachable and serving requests.', true, 'Connected', 'good', 'overview')} ${healthLayer('Providers', state.providers.length ? 'Provider health is reported by the runtime.' : 'Add and test a provider to establish runtime health.', state.providers.length > 0, state.providers.length ? `${state.providers.length} configured` : 'Not configured', state.providers.length ? 'good' : 'warn', 'providers')} ${healthLayer('Routing', routeCount ? 'Public models resolve to backend-owned routes.' : 'No public routes have been created yet.', routeCount > 0, routeCount ? `${routeCount} route${routeCount === 1 ? '' : 's'}` : 'Needs setup', routeCount ? 'good' : 'warn', 'routing')} ${healthLayer('Client access', state.snap.client_auth?.enabled ? 'Consumer credentials are enforced at the gateway.' : 'Requests are currently not gated by client keys.', Boolean(state.snap.client_auth?.enabled), state.snap.client_auth?.enabled ? 'Protected' : 'Open', state.snap.client_auth?.enabled ? 'good' : 'warn', 'settings')}</div><div class="split-grid"><section class="panel"><div class="section-heading compact"><div><span class="eyebrow">Execution map</span><h2>Live routing topology</h2></div><span class="live-status live">● Live state</span></div><div class="topology"><div class="topology-node client"><b>Client</b><small>OpenAI / Anthropic compatible</small></div><div class="topology-line"><span></span></div><div class="topology-node router"><b>NexaRoute</b><small>policy + fallback engine</small></div><div class="topology-line"><span></span></div><div class="topology-targets">${topologyTargets()}</div></div></section><section class="panel"><div class="section-heading compact"><div><span class="eyebrow">Recent signals</span><h2>Activity feed</h2></div><button class="button ghost small" data-go="activity">View all</button></div>${eventList(ev.slice(0, 5))}</section></div>`; }
  function healthLayer(title, desc, ok, label, kind, go) { return `<button class="health-layer ${kind}" data-go="${go}"><span class="health-mark ${kind}">${ok ? '✓' : '!'}</span><span><b>${title}</b><small>${desc}</small></span><span class="health-label ${kind}">${label}</span><span class="health-chevron">→</span></button>`; }
  function topologyTargets() { const ds = deployments().slice(0, 3); if (!ds.length) return `<div class="topology-empty"><b>No active target</b><small>Configure a provider and route to see execution targets.</small></div>`; return ds.map(d => { const p = providerForDeployment(d), h = (state.snap.health || []).find(x => x.deployment === d.id) || {}; return `<div class="target-node"><span class="target-dot ${statusClass(h.status)}"></span><span><b>${esc(d.model || d.id)}</b><small>${esc(p.name || d.provider_id || 'Provider')}</small></span></div>`; }).join(''); }
  function ensureVideoPolling() { if (!state.videoPoll) state.videoPoll = setInterval(() => { if (state.page === 'video' && !state.videoLoading) refreshVideo(); }, 5000); }
